"""Public worker failures contain fixed codes, never exception diagnostics."""
_KNOWN_VALIDATION_ERRORS = {'Checkpoint output limit exceeded; re-upload required': 'ASR_CHECKPOINT_INVALID', 'Checkpoint too large': 'ASR_CHECKPOINT_INVALID', 'Checkpoint checksum mismatch': 'ASR_CHECKPOINT_INVALID', 'Language must be auto, zh or en': 'ASR_LANGUAGE_INVALID', 'Pending audio expired; re-upload required': 'ASR_PENDING_EXPIRED', 'Settings changed; re-upload required': 'ASR_CHECKPOINT_INVALID', 'Invalid checkpoint chunk sequence': 'ASR_CHECKPOINT_INVALID', 'Checkpoint language mismatch': 'ASR_CHECKPOINT_INVALID', 'Model, source or algorithm identity changed; re-upload required': 'ASR_CHECKPOINT_INVALID', 'Source PCM hash mismatch; re-upload required': 'ASR_CHECKPOINT_INVALID', 'Invalid checkpoint sample count': 'ASR_CHECKPOINT_INVALID', 'Source hash mismatch; re-upload required': 'ASR_CHECKPOINT_INVALID', 'Invalid checkpoint word': 'ASR_CHECKPOINT_INVALID', 'Invalid input size': 'ASR_AUDIO_INVALID', 'No audio frames': 'ASR_AUDIO_INVALID', 'Content and MIME mismatch': 'ASR_AUDIO_INVALID', 'Local regular audio files only': 'ASR_AUDIO_INVALID', 'Missing Ogg end marker': 'ASR_AUDIO_INVALID', 'Incomplete M4A': 'ASR_AUDIO_INVALID', 'Invalid ID3 header': 'ASR_AUDIO_INVALID', 'Truncated MP3 header': 'ASR_AUDIO_INVALID', 'Unsupported audio/MP3 frame': 'ASR_AUDIO_INVALID', 'Truncated MP3 frame': 'ASR_AUDIO_INVALID', 'Invalid WAV framing': 'ASR_AUDIO_INVALID', 'Invalid input file or size': 'ASR_AUDIO_INVALID', 'Unsupported input source': 'ASR_AUDIO_INVALID', 'Invalid Ogg framing': 'ASR_AUDIO_INVALID', 'Chained/multiplexed/incomplete Ogg unsupported': 'ASR_AUDIO_INVALID', 'Truncated Ogg page': 'ASR_AUDIO_INVALID', 'Truncated Ogg payload': 'ASR_AUDIO_INVALID', 'Truncated M4A box': 'ASR_AUDIO_INVALID', 'Invalid M4A box size': 'ASR_AUDIO_INVALID', 'MP3 requires Xing/Info byte count for completeness': 'ASR_AUDIO_INVALID', 'Only mono 16 kHz PCM16 WAV accepted': 'ASR_AUDIO_INVALID', 'Invalid WAV duration or truncated payload': 'ASR_AUDIO_INVALID', 'Invalid, truncated or unsupported audio': 'ASR_AUDIO_INVALID', 'MP3 declared byte count missing/mismatch': 'ASR_AUDIO_INVALID', 'Decode deadline exceeded': 'ASR_DEADLINE', 'Decoded PCM duration/bytes limit exceeded': 'ASR_AUDIO_INVALID', 'Decoder diagnostics limit exceeded': 'ASR_AUDIO_INVALID', 'Local model missing. Set YANYU_MODEL_DIR to a faster-whisper-small snapshot containing model.bin; see README.md': 'ASR_MODEL_UNAVAILABLE'}

def public_error(exc):
    # Exact built-in ValueError only. No __str__, repr, subclass hooks or fuzzy matching.
    code = 'ASR_FAILED'
    if type(exc) is ValueError and len(exc.args) == 1 and type(exc.args[0]) is str:
        code = _KNOWN_VALIDATION_ERRORS.get(exc.args[0], code)
    return {'type': 'error', 'error_code': code, 'error': 'Local recognition failed; re-upload required'}
